export default {"html":"<p data-line=\"0\" class=\"code-line\">For my own reference.</p>\n<h2 id=\"1.-update-the-cli-to-the-latest-version\" data-line=\"2\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#1.-update-the-cli-to-the-latest-version\" aria-hidden=\"true\"></a> 1. Update the CLI to the latest version</h2>\n<p data-line=\"4\" class=\"code-line\">How much you install globally varies, but a full setup looks like this.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"6\"><span class=\"line\"><span style=\"color:#B392F0\">%</span><span style=\"color:#9ECBFF\"> npm</span><span style=\"color:#9ECBFF\"> install</span><span style=\"color:#9ECBFF\"> @ionic/cli@latest</span><span style=\"color:#9ECBFF\"> @angular/cli@latest</span><span style=\"color:#79B8FF\"> -g</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">%</span><span style=\"color:#9ECBFF\"> npm</span><span style=\"color:#9ECBFF\"> install</span><span style=\"color:#9ECBFF\"> @ionic/angular-toolkit@latest</span><span style=\"color:#79B8FF\"> -d</span></span>\n<span class=\"line\"></span></code></pre></div><h2 id=\"2.-rewrite-the-project's-angular.json\" data-line=\"11\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#2.-rewrite-the-project's-angular.json\" aria-hidden=\"true\"></a> 2. Rewrite the project's angular.json</h2>\n<div class=\"code-block-container\"><div class=\"code-block-filename-container\"><span class=\"code-block-filename\">json</span></div><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"13\"><span class=\"line\"><span class=\"diff-prefix\"> </span><span> {</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span>   \"sourceRoot\": \"src\",</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span>   \"projectType\": \"application\",</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span>   \"prefix\": \"app\",</span></span>\n<span class=\"line diff remove\"><span class=\"diff-prefix\">-</span><span>   \"schematics\": {},</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span>   \"schematics\": {</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span>     \"@ionic/angular-toolkit:page\": {</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span>       \"styleext\": \"scss\",</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span>       \"standalone\": true</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span>     },</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span>     \"@schematics/angular:component\": {</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span>       \"standalone\": true</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span>     }</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span>   }</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span> }</span></span>\n<span class=\"line\"><span></span></span></code></pre></div><h2 id=\"summary\" data-line=\"31\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#summary\" aria-hidden=\"true\"></a> Summary</h2>\n<p data-line=\"33\" class=\"code-line\">Simple enough. One caveat: if you have moved from RoutingModule to <code>provideRouter</code>, the routes file must follow this naming convention:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"35\"><span class=\"line\"><span>**.routes.ts </span></span>\n<span class=\"line\"><span></span></span></code></pre></div><p data-line=\"39\" class=\"code-line\">I had one file named <code>**.routing.ts</code>, and the CLI did not recognize it. After renaming it to <code>**.routes.ts</code>, the CLI picked it up correctly. Starter templates and CLI-generated projects use fixed router names, but if you create routes yourself, keep this in mind.</p>\n<p data-line=\"41\" class=\"code-line\">See you next time.</p>\n","headings":[{"id":"1.-update-the-cli-to-the-latest-version","text":"1. Update the CLI to the latest version","level":2},{"id":"2.-rewrite-the-project's-angular.json","text":"2. Rewrite the project's angular.json","level":2},{"id":"summary","text":"Summary","level":2}]} as const;
